function startRecording(){if(records.length>=12){toast('12 drives retained. Export and remove a drive before recording more.');return;}recording={schemaVersion:1,simulatorVersion:'1.1.0',steeringMapping:'speed-adaptive-7.5-mps2',featureSchema:'road-relative-v1',modelId:mode==='learned'?(road.sealed?blindModel?.id||neuralModel.id:neuralModel.id):null,id:crypto.randomUUID(),createdAt:new Date().toISOString(),track:{id:road.id,name:road.name,role:road.role,width:road.width,length:round(road.length),seed:road.seed,controlPoints:TRACKS[trackIndex].points},driver:mode,sampleRateHz:20,physicsRateHz:120,observationType:'state-and-road-sensors',startTime:state.time,frames:[],laps:[]};$('record-button').classList.add('recording');if(!running)setRunning(true);toast('Recording at 20 Hz. Press Record again to finish and save.');}
