function renderRecords(){const list=$('recordings-list');$('recording-count').textContent=records.length;$('export-button').disabled=!records.length;if(!records.length){list.innerHTML='<span class="empty-icon">◌</span><span>No drives recorded yet. Hit <b>Record drive</b> to capture your first attempt.</span><span class="data-format">JSON · 20 HZ</span>';return;}list.replaceChildren();const rows=document.createElement('div');rows.className='recording-rows';for(const rec of records.slice().reverse()){const row=document.createElement('div');row.className='recording-row';const title=document.createElement('b');title.textContent=rec.track.name;const source=document.createElement('span');source.textContent=rec.driver==='reference'?'REFERENCE':rec.driver==='learned'?'NEURAL':'MANUAL';const stats=document.createElement('span');stats.textContent=`${rec.duration.toFixed(1)} s · ${rec.frames.length.toLocaleString()} frames · ${rec.summary.score}/100`;const actions=document.createElement('div');const exp=document.createElement('button');exp.textContent='Export';exp.onclick=()=>download(rec,`vector-${rec.track.id}-${rec.id.slice(0,8)}.json`);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',`Remove ${rec.track.name} recording`);remove.style.marginLeft='6px';remove.onclick=()=>{records=records.filter(r=>r.id!==rec.id);persist();renderRecords();toast('Recording removed from this browser.');};actions.append(exp,remove);row.append(title,source,stats,actions);rows.append(row);}list.append(rows);}
function drawMinimap(){const c=$('minimap').getContext('2d'),w=220,h=150,padding=30;const xs=road.points.map(p=>p.x),zs=road.points.map(p=>p.z),minX=Math.min(...xs),maxX=Math.max(...xs),minZ=Math.min(...zs),maxZ=Math.max(...zs),scale=Math.min((w-padding*2)/(maxX-minX),(h-padding*2)/(maxZ-minZ));const toMap=p=>[(p.x-(maxX+minX)/2)*scale+w/2,(p.z-(maxZ+minZ)/2)*scale+h/2];c.clearRect(0,0,w,h);c.beginPath();road.points.forEach((p,i)=>{const [x,y]=toMap(p);i?c.lineTo(x,y):c.moveTo(x,y);});c.closePath();c.strokeStyle='#495a4b';c.lineWidth=9;c.stroke();c.strokeStyle='#a8ba8e';c.lineWidth=2;c.stroke();const start=toMap(road.points[0]);c.fillStyle='#edf1de';c.fillRect(start[0]-3,start[1]-3,6,6);if(options.ghost){const [x,y]=toMap(ghost);c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.fillStyle='#edf8e888';c.fill();}const [x,y]=toMap(state);c.save();c.translate(x,y);c.rotate(-state.yaw);c.beginPath();c.moveTo(0,7);c.lineTo(-4,-4);c.lineTo(4,-4);c.closePath();c.fillStyle='#d7f878';c.shadowColor='#c8ed77';c.shadowBlur=8;c.fill();c.restore();}
