const keyMap={arrowup:'w',arrowdown:'s',arrowleft:'a',arrowright:'d'};
window.addEventListener('keydown',e=>{if($('modal').open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const key=keyMap[e.key.toLowerCase()]||e.key.toLowerCase();if(['w','a','s','d',' ','r','c','escape'].includes(key)){e.preventDefault();if(e.repeat&&['r','c','escape'].includes(key))return;if(key==='r'){reset();return;}if(key==='c'){setCamera((scene.cameraMode+1)%3);return;}if(key==='escape'){setRunning(false);if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});return;}if(key==='w'&&!running){setRunning(true);}keys.add(key);}});
window.addEventListener('keyup',e=>keys.delete(keyMap[e.key.toLowerCase()]||e.key.toLowerCase()));window.addEventListener('blur',()=>{if(running)setRunning(false);keys.clear();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)setRunning(false);});
